library(arrow); library(dplyr); library(lubridate); library(ggplot2)

# Load timeline parquets (full database — no clean-energy filter)
ce  &lt;- read_parquet("data/analysis/_timeline/timeline_ce.parquet")
ea  &lt;- read_parquet("data/analysis/_timeline/timeline_ea.parquet")
eis &lt;- read_parquet("data/analysis/_timeline/timeline_eis.parquet")
fr  &lt;- read_parquet("data/analysis/federal_register/federal_register.parquet")
projects &lt;- read_parquet("data/analysis/projects_combined.parquet")

# --- Initiation date merge ---
# NOI dates are authoritative (not a fallback); override bert_initiation_date
merge_initiation &lt;- function(tl) {
  tl |&gt;
    left_join(
      fr |&gt; select(project_id, noi_publication_date),
      by = "project_id"
    ) |&gt;
    mutate(
      initiation_date = coalesce(
        as.Date(noi_publication_date),  # wins when present
        as.Date(bert_initiation_date)
      )
    )
}

# Decision date: bert_decision_date -&gt; llm_decision_date
add_decision_date &lt;- function(tl) {
  tl |&gt; mutate(
    decision_date = coalesce(
      as.Date(bert_decision_date),
      as.Date(llm_decision_date)
    )
  )
}

ce  &lt;- merge_initiation(ce)  |&gt; add_decision_date()
ea  &lt;- merge_initiation(ea)  |&gt; add_decision_date()
eis &lt;- merge_initiation(eis) |&gt; add_decision_date()

# --- Duration calculation ---
calc_durations &lt;- function(tl, source) {
  tl |&gt;
    filter(!is.na(initiation_date), !is.na(decision_date)) |&gt;
    mutate(
      duration_days = as.numeric(decision_date - initiation_date),
      process_type = source,
      # CEQ regulation periods
      period = case_when(
        decision_date &gt;= as.Date("2023-08-16") ~ "post_FRA",
        decision_date &gt;= as.Date("2022-08-16") ~ "post_IRA",
        decision_date &gt;= as.Date("2020-09-14") ~ "post_2020_CEQ",
        TRUE ~ "pre_2020"
      )
    ) |&gt;
    filter(duration_days &gt; 0, duration_days &lt; 365 * 25)
}

durations &lt;- bind_rows(
  calc_durations(ce, "CE"),
  calc_durations(ea, "EA"),
  calc_durations(eis, "EIS")
) |&gt;
  left_join(
    projects |&gt; select(project_id, agency_name, project_energy_type, state),
    by = "project_id"
  )

# --- Analyses ---

# 1. Summary by process type × period
period_summary &lt;- durations |&gt;
  group_by(process_type, period) |&gt;
  summarise(
    n = n(),
    median_days = median(duration_days),
    p25 = quantile(duration_days, 0.25),
    p75 = quantile(duration_days, 0.75),
    mean_days = mean(duration_days),
    .groups = "drop"
  )

# 2. Pre/post-FRA statistical test (Wilcoxon rank-sum; durations are right-skewed)
for (pt in c("CE", "EA", "EIS")) {
  pre &lt;- durations |&gt; filter(process_type == pt, period == "pre_2020") |&gt; pull(duration_days)
  post &lt;- durations |&gt; filter(process_type == pt, period == "post_FRA") |&gt; pull(duration_days)
  if (length(pre) &gt; 10 && length(post) &gt; 10) {
    test &lt;- wilcox.test(pre, post)
    cat(sprintf("%s pre vs post-FRA: W=%.1f, p=%.4f\n", pt, test$statistic, test$p.value))
  }
}

# 3. Agency-level comparison (top 10 agencies by project count)
top_agencies &lt;- durations |&gt;
  count(agency_name, sort=TRUE) |&gt;
  head(10) |&gt;
  pull(agency_name)

agency_summary &lt;- durations |&gt;
  filter(agency_name %in% top_agencies) |&gt;
  group_by(agency_name, process_type) |&gt;
  summarise(n = n(), median_days = median(duration_days), .groups = "drop")

# 4. Outliers (&gt;2× IQR for case study packaging)
outliers &lt;- durations |&gt;
  group_by(process_type) |&gt;
  mutate(iqr = IQR(duration_days), q75 = quantile(duration_days, 0.75)) |&gt;
  filter(duration_days &gt; q75 + 2 * iqr) |&gt;
  select(project_id, process_type, duration_days, period, agency_name) |&gt;
  arrange(desc(duration_days))

# --- Coverage caveat ---
coverage &lt;- durations |&gt;
  count(process_type, name = "n_with_duration") |&gt;
  left_join(
    bind_rows(
      ce |&gt; count() |&gt; mutate(process_type = "CE"),
      ea |&gt; count() |&gt; mutate(process_type = "EA"),
      eis |&gt; count() |&gt; mutate(process_type = "EIS")
    ) |&gt; rename(n_total = n),
    by = "process_type"
  ) |&gt;
  mutate(coverage_pct = n_with_duration / n_total)

cat("Coverage rates:\n")
print(coverage)

# --- Outputs ---
dir.create("output/deliverable04", recursive=TRUE, showWarnings=FALSE)
write.csv(period_summary, "output/deliverable04/timelines_by_period.csv", row.names=FALSE)
write.csv(agency_summary, "output/deliverable04/timelines_by_agency.csv", row.names=FALSE)
write.csv(outliers, "output/deliverable04/timelines_outliers.csv", row.names=FALSE)
write.csv(coverage, "output/deliverable04/timelines_coverage.csv", row.names=FALSE)

library(arrow); library(dplyr); library(lubridate)

ce_adoption &lt;- read_parquet("data/analysis/ce_adoption/ce_adoption_fr.parquet")
ce_timelines &lt;- read_parquet("data/analysis/_timeline/timeline_ce.parquet")
projects &lt;- read_parquet("data/analysis/projects_combined.parquet")

# 1. CE adoption notice counts post-FRA by agency
adoption_counts &lt;- ce_adoption |&gt;
  count(agency_name, sort=TRUE) |&gt;
  mutate(publication_date = as.Date(publication_date))

# 2. For matched projects: duration before vs. after CE adoption notice
# (N will be small — likely &lt; 50 matched projects)
matched &lt;- ce_adoption |&gt;
  filter(!is.na(matched_project_id)) |&gt;
  select(matched_project_id, publication_date, agency_name) |&gt;
  rename(project_id = matched_project_id, adoption_date = publication_date)

matched_timelines &lt;- ce_timelines |&gt;
  filter(!is.na(bert_initiation_date), !is.na(bert_decision_date)) |&gt;
  inner_join(matched, by = "project_id") |&gt;
  mutate(
    duration_days = as.numeric(as.Date(bert_decision_date) - as.Date(bert_initiation_date)),
    post_adoption = as.Date(bert_decision_date) &gt;= as.Date(adoption_date)
  )

duration_compare &lt;- matched_timelines |&gt;
  group_by(agency_name, post_adoption) |&gt;
  summarise(n = n(), median_days = median(duration_days, na.rm=TRUE), .groups="drop")

write.csv(adoption_counts, "output/deliverable04/ce_adoption_counts.csv", row.names=FALSE)
write.csv(duration_compare, "output/deliverable04/ce_adoption_duration_compare.csv", row.names=FALSE)

library(arrow)
library(dplyr)
library(ggplot2)
library(tidyr)

sig &lt;- read_parquet("data/analysis/significance/projects_significance.parquet")
projects &lt;- read_parquet("data/analysis/projects_combined.parquet")
df &lt;- left_join(sig, projects, by = "project_id")

# 1. Determination rates by resource area
by_area &lt;- df |&gt;
  count(resource_area, determination) |&gt;
  group_by(resource_area) |&gt;
  mutate(pct = n / sum(n))

# 2. Mitigation flag rates (proportion of determinations with mitigation conditions)
mitigation_rates &lt;- df |&gt;
  filter(determination %in% c("less_than_significant_with_mitigation", "significant_and_unavoidable")) |&gt;
  group_by(resource_area) |&gt;
  summarise(mitigation_pct = mean(mitigation_flag))

# 3. Rates by agency and process type
by_agency &lt;- df |&gt;
  count(agency_name, determination) |&gt;
  group_by(agency_name) |&gt;
  mutate(pct = n / sum(n))

# 4. Mitigated FONSI patterns
fonsi_patterns &lt;- df |&gt;
  filter(determination == "no_significant_impact") |&gt;
  group_by(resource_area, mitigation_flag) |&gt;
  count()

# Outputs
write.csv(by_area, "output/deliverable02/significance_by_resource_area.csv", row.names=FALSE)
write.csv(mitigation_rates, "output/deliverable02/mitigation_rates.csv", row.names=FALSE)
write.csv(by_agency, "output/deliverable02/significance_by_agency.csv", row.names=FALSE)
write.csv(fonsi_patterns, "output/deliverable02/fonsi_patterns.csv", row.names=FALSE)

