library(arrow); library(dplyr); library(tidyr); library(ggplot2); library(scales)

projects &lt;- read_parquet("data/analysis/projects_combined.parquet")
technology &lt;- read_parquet("data/analysis/projects_technology.parquet")
reviews &lt;- read_parquet("data/analysis/projects_reviews.parquet")

df &lt;- projects |&gt;
  left_join(technology, by = "project_id") |&gt;
  left_join(reviews, by = "project_id")



1. CE/EA/EIS rates by fossil vs. clean × linear vs. non-linear:
rate_table &lt;- df |&gt;
  filter(!is.na(process_type), !is.na(project_energy_type)) |&gt;
  mutate(
    energy_group = ifelse(project_energy_type == "Clean", "Clean", "Fossil"),
    project_class = ifelse(is_linear, "Linear", "Non-linear")
  ) |&gt;
  count(energy_group, project_class, process_type) |&gt;
  group_by(energy_group, project_class) |&gt;
  mutate(pct = n / sum(n))
2. Chi-square test:
contingency &lt;- df |&gt;
  filter(project_energy_type %in% c("Clean", "Fossil"), !is.na(process_type)) |&gt;
  count(project_energy_type, process_type) |&gt;
  pivot_wider(names_from = process_type, values_from = n, values_fill = 0)

chisq.test(contingency[, -1])
3. Geographic distribution:
state_rates &lt;- df |&gt;
  count(state, process_type) |&gt;
  group_by(state) |&gt;
  mutate(pct = n / sum(n))
4. Programmatic/tiered review rates:
programmatic &lt;- df |&gt;
  filter(process_type == "EIS") |&gt;
  count(is_programmatic, is_tiered) |&gt;
  mutate(pct = n / sum(n))



dir.create("output/deliverable03", recursive=TRUE, showWarnings=FALSE)
write.csv(rate_table, "output/deliverable03/review_rates_by_type.csv", row.names=FALSE)
write.csv(state_rates, "output/deliverable03/review_rates_by_state.csv", row.names=FALSE)
write.csv(programmatic, "output/deliverable03/programmatic_summary.csv", row.names=FALSE)

