library(arrow); library(dplyr); library(lubridate)

# Load timeline data — merge initiation dates with NOI override
ce &lt;- read_parquet("data/analysis/_timeline/timeline_ce.parquet")
ea &lt;- read_parquet("data/analysis/_timeline/timeline_ea.parquet")
eis &lt;- read_parquet("data/analysis/_timeline/timeline_eis.parquet")
fr  &lt;- read_parquet("data/analysis/federal_register/federal_register.parquet")
projects &lt;- read_parquet("data/analysis/projects_combined.parquet")

# Merge NOI dates — noi_publication_date wins over bert_initiation_date
merge_initiation &lt;- function(tl, fr_df) {
  tl |&gt;
    left_join(fr_df |&gt; select(project_id, noi_publication_date), by = "project_id") |&gt;
    mutate(
      initiation_date = coalesce(noi_publication_date, bert_initiation_date)
    )
}

ce  &lt;- merge_initiation(ce, fr)
ea  &lt;- merge_initiation(ea, fr)
eis &lt;- merge_initiation(eis, fr)

# Calculate durations
calc_durations &lt;- function(tl, source) {
  tl |&gt;
    filter(!is.na(initiation_date), !is.na(bert_decision_date)) |&gt;
    mutate(
      duration_days = as.numeric(bert_decision_date - initiation_date),
      process_type = source,
      period = case_when(
        bert_decision_date &gt;= as.Date("2023-08-16") ~ "post_FRA",
        bert_decision_date &gt;= as.Date("2020-09-14") ~ "post_2020_CEQ",
        TRUE ~ "pre_2020"
      )
    ) |&gt;
    filter(duration_days &gt; 0, duration_days &lt; 365 * 20)  # sanity bounds
}

durations &lt;- bind_rows(
  calc_durations(ce, "CE"),
  calc_durations(ea, "EA"),
  calc_durations(eis, "EIS")
) |&gt;
  left_join(projects |&gt; select(project_id, agency_name, project_energy_type, is_linear), by = "project_id")

# Analyses: median by period × process type; by energy type; outliers
summary_table &lt;- durations |&gt;
  group_by(process_type, period) |&gt;
  summarise(
    n = n(),
    median_days = median(duration_days),
    p25 = quantile(duration_days, 0.25),
    p75 = quantile(duration_days, 0.75),
    .groups = "drop"
  )

outliers &lt;- durations |&gt;
  group_by(process_type) |&gt;
  mutate(iqr = IQR(duration_days), q75 = quantile(duration_days, 0.75)) |&gt;
  filter(duration_days &gt; q75 + 2 * iqr) |&gt;
  select(project_id, process_type, duration_days, agency_name)

write.csv(summary_table, "output/deliverable03/durations_summary.csv", row.names=FALSE)
write.csv(outliers, "output/deliverable03/durations_outliers.csv", row.names=FALSE)

library(arrow); library(dplyr); library(lubridate); library(ggplot2); library(zoo)

citations &lt;- read_parquet("data/analysis/law_citations/ce_law_citations.parquet")
projects  &lt;- read_parquet("data/analysis/projects_combined.parquet")

# Merge on CE projects with dates
ce &lt;- projects |&gt;
  filter(process_type == "CE", !is.na(start_date)) |&gt;
  mutate(start_date = as.Date(start_date))

# --- 1. Temporal trend analysis ---

# Monthly CE counts
monthly &lt;- ce |&gt;
  mutate(month = floor_date(start_date, "month")) |&gt;
  count(month, name = "n_projects") |&gt;
  filter(month &gt;= as.Date("2007-01-01"), month &lt;= as.Date("2025-01-01")) |&gt;
  arrange(month) |&gt;
  mutate(
    n_smoothed = rollmean(n_projects, k=3, fill=NA, align="right"),
    # Spike window flags
    arra_window = month &gt;= as.Date("2009-03-01") & month &lt;= as.Date("2010-02-28"),
    bil_window  = month &gt;= as.Date("2021-12-01") & month &lt;= as.Date("2022-11-30"),
    ira_window  = month &gt;= as.Date("2022-09-01") & month &lt;= as.Date("2023-08-31")
  )

# Spike summary: mean monthly CEs in window vs. 24-month pre-law baseline
spike_summary &lt;- bind_rows(
  tibble(law="ARRA",
    window_mean = monthly |&gt; filter(arra_window) |&gt; pull(n_projects) |&gt; mean(),
    baseline_mean = monthly |&gt;
      filter(month &gt;= as.Date("2007-03-01"), month &lt;= as.Date("2009-02-28")) |&gt;
      pull(n_projects) |&gt; mean()
  ),
  tibble(law="BIL",
    window_mean = monthly |&gt; filter(bil_window) |&gt; pull(n_projects) |&gt; mean(),
    baseline_mean = monthly |&gt;
      filter(month &gt;= as.Date("2019-12-01"), month &lt;= as.Date("2021-11-30")) |&gt;
      pull(n_projects) |&gt; mean()
  ),
  tibble(law="IRA",
    window_mean = monthly |&gt; filter(ira_window) |&gt; pull(n_projects) |&gt; mean(),
    baseline_mean = monthly |&gt;
      filter(month &gt;= as.Date("2020-09-01"), month &lt;= as.Date("2022-08-31")) |&gt;
      pull(n_projects) |&gt; mean()
  )
) |&gt; mutate(spike_ratio = window_mean / baseline_mean)

# --- 2. Spike characterization ---

# Law passage dates
law_dates &lt;- tibble(
  law = c("ARRA", "BIL", "IRA"),
  passage_date = as.Date(c("2009-02-17", "2021-11-15", "2022-08-16")),
  window_start = as.Date(c("2009-03-01", "2021-12-01", "2022-09-01")),
  window_end   = as.Date(c("2010-02-28", "2022-11-30", "2023-08-31"))
)

characterize_spike &lt;- function(ce_df, window_start, window_end, baseline_start, baseline_end) {
  spike &lt;- ce_df |&gt; filter(start_date &gt;= window_start, start_date &lt;= window_end) |&gt; mutate(period = "spike")
  baseline &lt;- ce_df |&gt; filter(start_date &gt;= baseline_start, start_date &lt;= baseline_end) |&gt; mutate(period = "baseline")
  bind_rows(spike, baseline) |&gt;
    count(period, project_energy_type) |&gt;
    group_by(period) |&gt;
    mutate(pct = n / sum(n))
}

arra_char &lt;- characterize_spike(ce,
  as.Date("2009-03-01"), as.Date("2010-02-28"),
  as.Date("2007-03-01"), as.Date("2009-02-28")
)
bil_char &lt;- characterize_spike(ce,
  as.Date("2021-12-01"), as.Date("2022-11-30"),
  as.Date("2019-12-01"), as.Date("2021-11-30")
)
ira_char &lt;- characterize_spike(ce,
  as.Date("2022-09-01"), as.Date("2023-08-31"),
  as.Date("2020-09-01"), as.Date("2022-08-31")
)

# --- 3. Citation rates ---
# What % of spike-window CEs have explicit law citation?
citation_rates &lt;- ce |&gt;
  mutate(
    arra_window = start_date &gt;= as.Date("2009-03-01") & start_date &lt;= as.Date("2010-02-28"),
    bil_window  = start_date &gt;= as.Date("2021-12-01") & start_date &lt;= as.Date("2022-11-30"),
    ira_window  = start_date &gt;= as.Date("2022-09-01") & start_date &lt;= as.Date("2023-08-31")
  ) |&gt;
  left_join(citations, by = "project_id") |&gt;
  group_by(arra_window) |&gt;
  summarise(
    n = n(),
    n_cited = sum(!is.na(law_name) & law_name == "ARRA"),
    pct_cited = n_cited / n
  )
